// Achata os sets do setlist.fm em uma lista de faixas.
// A API devolve XML por padrao (no XML o wrapper se chama 'sets', no JSON e 'set'),
// e o n8n pode entregar isso ja convertido em objeto. O parse abaixo aceita os dois.
const raw = $input.all()[0]?.json ?? {};

function achatar(valor) {
  if (typeof valor === 'string') {
    try {
      return achatar(JSON.parse(valor));
    } catch {
      return null;
    }
  }
  if (Array.isArray(valor)) {
    for (const item of valor) {
      const achado = achatar(item);
      if (achado) return achado;
    }
    return null;
  }
  if (valor && typeof valor === 'object') {
    if (Array.isArray(valor.setlist)) return valor.setlist[0] ?? null;
    if (valor.artist || valor.set || valor.sets || valor.song) return valor;
    for (const chave of ['body', 'data', 'response']) {
      const achado = achatar(valor[chave]);
      if (achado) return achado;
    }
  }
  return null;
}

// No XML a hierarquia vem aninhada: sets -> set -> song.
function conjuntosDo(valor) {
  if (Array.isArray(valor)) return valor.flatMap(conjuntosDo);
  if (!valor || typeof valor !== 'object') return [];
  if (valor.set !== undefined) return conjuntosDo(valor.set);
  if (valor.sets !== undefined) return conjuntosDo(valor.sets);
  if (valor.song !== undefined || valor.songs !== undefined) return [valor];
  return [];
}

function musicasDo(conjunto) {
  if (Array.isArray(conjunto)) return conjunto.flatMap(musicasDo);
  if (!conjunto || typeof conjunto !== 'object') return [];
  if (conjunto.song !== undefined) return musicasDo(conjunto.song);
  if (conjunto.songs !== undefined) return musicasDo(conjunto.songs);
  return [conjunto];
}

const sl = achatar(raw) ?? {};
const city = sl.venue?.city ?? {};
const venue = [sl.venue?.name, city.name, city.country?.name].filter(Boolean).join(', ');
const rawDate = sl.eventDate || '';
// eventDate vem como dd-MM-yyyy.
const date = /^\d{2}-\d{2}-\d{4}$/.test(rawDate) ? rawDate.split('-').join('/') : rawDate;

const songs = [];
for (const conjunto of conjuntosDo(sl.set ?? sl.sets ?? sl)) {
  for (const item of musicasDo(conjunto)) {
    const nome = item.name ?? item.song?.name ?? item.title;
    if (!nome) continue;
    // Quem tocou: o convidado ('with') tem precedencia sobre o artista do show.
    const performer = item.with?.name || sl.artist?.name || '';
    const cover = typeof item.cover === 'object' ? item.cover?.name || '' : item.coverArtist?.name || '';
    songs.push({
      song: nome,
      artist: performer,
      cover,
      query: `${performer} ${nome}`.trim(),
    });
  }
}

return [{
  json: {
    artist: sl.artist?.name ?? '',
    venue,
    date,
    tour: sl.tour?.name ?? '',
    url: sl.url ?? '',
    songs,
    // Se nao achou musica, mostra as chaves que vieram para diagnosticar o formato.
    ...(songs.length ? {} : { debug: { chavesDaResposta: Object.keys(raw), chavesDoSetlist: Object.keys(sl) } }),
  },
}];

// Uma linha por faixa, ja com o id da playlist.
const playlist = $('Criar playlist').first().json;
const meta = $('Extrair setlist').first().json;

return meta.songs.map((s) => ({
  json: {
    ...s,
    playlistId: playlist.id,
    metaArtist: meta.artist,
    metaVenue: meta.venue,
    metaDate: meta.date,
    metaUrl: meta.url,
  },
}));

// Escolhe o melhor video da busca. A busca e feita uma vez por faixa,
// entao a ordem dos resultados bate com a ordem das faixas.
// Regra: descarta o que tem 'live' no titulo e, entre o resto, prefere o video
// que mais combina com o nome da musica e o canal do artista.
const norm = (s) => String(s ?? '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
const semVogal = (s) => norm(s).replace(/[aeiou]/g, '');

// A grafia nem sempre bate: o setlist.fm chama de 'Elunor', o YouTube de 'Eleanor'.
// Comparar sem vogais resolve: 'lnr' == 'lnr'.
function pareceMusica(titulo, musica) {
  const t = norm(titulo);
  const m = norm(musica);
  if (!m) return false;
  if (t.includes(m)) return true;
  const mv = semVogal(musica);
  return mv.length >= 3 && semVogal(titulo).includes(mv);
}

const AO_VIVO = /live|concert|concerto|konzert|ao vivo|en vivo|reuni|cover|covered|remix|unplugged|on stage|festival|tribute/i;

const faixas = $('Preparar faixas').all();
const buscas = $('Buscar video').all();
const out = [];

for (let i = 0; i < buscas.length; i++) {
  const faixa = faixas[i]?.json ?? {};
  const items = buscas[i]?.json?.items ?? [];

  if (!items.length) {
    out.push({ json: { ...faixa, videoId: '', videoTitle: '', videoChannel: '', videoUrl: '' } });
    continue;
  }

  const artistN = norm(faixa.artist);
  // O canal pode vir sem separador: 'TheGatheringband' vs 'The Gathering'.
  const artistCompacto = artistN.replace(/\s+/g, '');
  const contemArtista = (texto) => {
    const t = norm(texto);
    if (!artistN) return false;
    return t.includes(artistN) || t.replace(/\s+/g, '').includes(artistCompacto);
  };

  let melhor = null;
  let melhorScore = -Infinity;
  let melhorSemLive = null;
  let melhorSemLiveScore = -Infinity;

  for (const item of items) {
    const snippet = item.snippet || {};
    const title = norm(snippet.title);
    const channel = norm(snippet.channelTitle);
    const aoVivo = AO_VIVO.test(snippet.title || '');

    let score = 0;
    if (pareceMusica(snippet.title || '', faixa.song)) score += 3;
    if (contemArtista(snippet.channelTitle)) score += 3;
    if (contemArtista(snippet.title)) score += 1;
    if (aoVivo) score -= 6;

    if (score > melhorScore) {
      melhorScore = score;
      melhor = item;
    }
    if (!aoVivo && score > melhorSemLiveScore) {
      melhorSemLiveScore = score;
      melhorSemLive = item;
    }
  }

  // Prefere qualquer video sem 'live' no titulo; so usa a live se nao houver outro.
  const escolhido = melhorSemLive || melhor;
  const snippet = escolhido.snippet || {};
  const videoId = escolhido.id?.videoId ?? '';
  out.push({
    json: {
      ...faixa,
      videoId,
      videoTitle: snippet.title || '',
      videoChannel: snippet.channelTitle || '',
      videoUrl: videoId ? `https://www.youtube.com/watch?v=${videoId}` : '',
    },
  });
}

return out;

// Monta a resposta final. Os dados das faixas vem do no 'Escolher video',
// porque o no do YouTube substitui o item de entrada pela resposta da API.
const playlist = $('Criar playlist').first().json;
const meta = $('Extrair setlist').first().json;
const escolhidos = $('Escolher video').all().map((i) => i.json);

const tracks = [];
const missing = [];
for (const it of escolhidos) {
  if (!it.videoId) {
    missing.push(it.song);
    continue;
  }
  tracks.push({
    song: it.song,
    videoUrl: it.videoUrl,
    videoTitle: it.videoTitle,
    videoChannel: it.videoChannel || '',
    videoDuration: it.videoDuration || 0,
    cover: it.cover,
  });
}

return [{
  json: {
    playlistUrl: `https://www.youtube.com/playlist?list=${playlist.id}`,
    title: playlist.snippet?.title ?? '',
    artist: meta.artist,
    venue: meta.venue,
    date: meta.date,
    tracks,
    missing,
  },
}];
